// Check if lead exists, create if not
const lookupResult = $json;
const phone = $node['Webhook'].json.From;
const inboundText = $node['Webhook'].json.Body;

let lead;
let isNewLead = false;

if (lookupResult && lookupResult.lead_id) {
  lead = lookupResult;
} else {
  // Create new lead structure
  isNewLead = true;
  lead = {
    lead_id: 'lead_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    phone: phone,
    name: null,
    city: null,
    address: null,
    pool_type: null,
    pool_size: null,
    pool_condition: null,
    service_type: null,
    status: 'new',
    last_message_at: new Date().toISOString(),
    next_followup_at: null,
    notes: null
  };
}

return [{
  json: {
    lead: lead,
    isNewLead: isNewLead,
    inboundText: inboundText,
    phone: phone
  }
}];

// Prepare data for Claude API call
const lead = $('Process Lead').item.json.lead;
const inboundText = $('Process Lead').item.json.inboundText;

// Get last 10 messages from history
const historyItems = $items('Get History') || [];
const messages = historyItems
  .map(item => item.json)
  .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp))
  .slice(-10);

// Convert config items to object
const configItems = $items('Get Config') || [];
const config = {};
configItems.forEach(item => {
  if (item.json.key && item.json.value !== undefined) {
    config[item.json.key] = item.json.value;
  }
});

// Build conversation history for Claude
let conversationHistory = messages.map(m => {
  return (m.direction === 'in' ? 'Customer: ' : 'Agent: ') + m.text;
}).join('\n');

const systemPrompt = `You are a scheduling assistant for a local pool cleaning company.

GOAL: Convert inquiries into booked appointments or qualified leads.

BUSINESS CONFIG:
- Business Name: ${config.business_name || 'Pool Cleaning Co'}
- Service Cities: ${config.service_cities || 'Not configured'}
- Weekly Pricing: ${config.pricing_weekly_range || '$140-$180/month'}
- Bi-weekly Pricing: ${config.pricing_biweekly_range || '$90-$120/month'}
- One-time Pricing: ${config.pricing_onetime_range || '$150-$300'}
- Office Hours: ${config.office_hours || '9am-5pm'}

RULES:
1. Be brief and friendly (1-2 sentences max)
2. Ask ONE question at a time
3. Check service city FIRST - politely decline if outside area
4. Give price RANGES only, never exact pricing
5. If uncertain or customer requests human: set intent=handoff
6. Output MUST be valid JSON only - no extra text

QUALIFICATION FLOW:
1. Greet + ask city
2. Confirm residential vs commercial
3. Ask pool size (standard/large/not sure)
4. Ask service needed (weekly/biweekly/one-time/quote)
5. Provide pricing range
6. Offer to book

OUTPUT FORMAT (strict JSON):
{
  "reply_text": "Your message to send",
  "lead_status": "new|qualifying|qualified|booked|unqualified|handoff",
  "intent": "ask_question|give_pricing|book|follow_up|handoff",
  "fields_extracted": {
    "name": null,
    "city": null,
    "address": null,
    "pool_type": null,
    "pool_size": null,
    "pool_condition": null,
    "service_type": null
  },
  "missing_fields": ["city", "pool_type"],
  "booking_request": {
    "preferred_days": null,
    "preferred_times": null
  },
  "handoff_reason": null
}`;

const userMessage = `CURRENT LEAD RECORD:
${JSON.stringify(lead, null, 2)}

CONVERSATION HISTORY:
${conversationHistory || '(new conversation)'}

NEW MESSAGE FROM CUSTOMER:
${inboundText}

Respond with JSON only.`;

return [{
  json: {
    systemPrompt: systemPrompt,
    userMessage: userMessage,
    lead: lead,
    config: config
  }
}];

// Parse Claude's JSON response
const response = $json;
const prepData = $node['Prepare Claude Request'].json;
const config = prepData.config;
const lead = prepData.lead;

let parsed;
let replyText;

try {
  const text = response.content[0].text;
  // Try to parse as JSON
  parsed = JSON.parse(text);
  replyText = parsed.reply_text;
} catch (e) {
  // If JSON parsing fails, try to extract just the reply
  try {
    const text = response.content[0].text;
    // Maybe Claude added extra text, try to find JSON
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
      replyText = parsed.reply_text;
    } else {
      throw new Error('No JSON found');
    }
  } catch (e2) {
    // Fallback
    parsed = {
      reply_text: 'Thanks for reaching out! Someone will get back to you shortly.',
      lead_status: lead.status || 'new',
      intent: 'handoff',
      fields_extracted: {},
      missing_fields: [],
      booking_request: {},
      handoff_reason: 'Failed to parse AI response'
    };
    replyText = parsed.reply_text;
  }
}

// Merge extracted fields with existing lead data
const fieldsExtracted = parsed.fields_extracted || {};
const updatedLead = { ...lead };

Object.keys(fieldsExtracted).forEach(key => {
  if (fieldsExtracted[key] !== null && fieldsExtracted[key] !== undefined) {
    updatedLead[key] = fieldsExtracted[key];
  }
});

// Update status
updatedLead.status = parsed.lead_status || lead.status;
updatedLead.last_message_at = new Date().toISOString();

// Set follow-up if not booked
if (parsed.lead_status !== 'booked' && parsed.lead_status !== 'unqualified' && parsed.lead_status !== 'handoff') {
  updatedLead.next_followup_at = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
} else {
  updatedLead.next_followup_at = null;
}

return [{
  json: {
    reply_text: replyText,
    parsed_response: parsed,
    lead: updatedLead,
    config: config,
    twilio_number: config.twilio_number
  }
}];

